import json
def strict_question(raw):
    def unique(pairs):
        out={}
        for key,value in pairs:
            if key in out:raise ValueError('duplicate')
            out[key]=value
        return out
    def nonfinite(value):raise ValueError('nonfinite')
    if not isinstance(raw,str):raise ValueError('type')
