def selected_quotes(value,selected):
    if not isinstance(value,dict) or set(value)!={'quotes'}:raise ValueError('envelope')
    rows=value['quotes']
    if not isinstance(rows,list) or not 1<=len(rows)<=3:raise ValueError('count')
    seen=set();out=[]
    for row in rows:
        if not isinstance(row,dict) or set(row)!={'citation','text'}:raise ValueError('row')
        label,text=row['citation'],row['text']
        if not isinstance(label,str) or not isinstance(text,str):raise ValueError('types')
        if label in seen or label not in selected or text!=selected[label]:raise ValueError('quote')
        seen.add(label);out.append((label,text))
    return tuple(out)

