import re
def security_event(request_id,reason,candidate_count,citation_count,blocked_chunk_count):
    reasons=('ok','input_invalid','input_blocked','no_context','output_blocked','source_changed')
    if not isinstance(request_id,str) or re.fullmatch(r'[A-Za-z0-9_-]{1,64}',request_id) is None:
        raise ValueError('request_id')
    if not isinstance(reason,str) or reason not in reasons:raise ValueError('reason')
    counts=(candidate_count,citation_count,blocked_chunk_count)
    if any(type(n) is not int or n<0 for n in counts):raise ValueError('counts')
    if citation_count>3 or (reason=='ok')!=(citation_count>0):raise ValueError('citations')
    return dict(schema='week11-security-event/1.0.0',request_id=request_id,
        outcome='answered' if reason=='ok' else 'refused',reason=reason,
        candidate_count=candidate_count,citation_count=citation_count,
        blocked_chunk_count=blocked_chunk_count)

import json
def fit_context(rows,budget):
    if type(budget) is not int or not 2<=budget<=1400:raise ValueError('budget')
    kept=[];text='[]'
    for row in rows:
        proposed=json.dumps(kept+[row],sort_keys=True,ensure_ascii=False,separators=(',',':'))
        if len(proposed)>budget:break
        kept.append(row);text=proposed
    return kept,text

